import{_ as n,c as t,e,a as i,d as l,w as r,r as p,o as h,b as k}from"./app-CHV3pEDi.js";const d="/assets/%E5%8E%9F%E5%AD%90%E6%93%8D%E4%BD%9C%E4%B8%8E%E6%99%AE%E9%80%9A%E6%93%8D%E4%BD%9C%E5%AF%B9%E6%AF%94-Z22ULder.jpg",o="/assets/LDREX%E4%B8%8ESTREX%E9%85%8D%E5%90%88%E5%AE%9E%E7%8E%B0%E5%8E%9F%E5%AD%90%E6%93%8D%E4%BD%9C-fSAP-NzM.jpg",g={};function c(A,s){const a=p("VPLink");return h(),t("div",null,[s[4]||(s[4]=e('<p>当工程中引入RT-Thread等RTOS后，我们经常会碰到多任务访问共享资源冲突的问题：</p><blockquote><p>例如，两个任务同时对全局变量counter进行自增操作时，有可能出现最终自增结果错误的问题。 要解决这个问题，常见的做法是利用关中断或者互斥锁来保护，避免操作过程中被打断。</p></blockquote><p>不过，对于counter++这种简单的操作，使用关中断或互斥锁有点杀鸡用牛刀的感觉。</p><p>实际上，在有些CPU架构上，还有另外一种更好的方案可以替代，那就是利用原子操作相关的指令。</p><h2 id="什么是原子操作" tabindex="-1"><a class="header-anchor" href="#什么是原子操作"><span>什么是原子操作</span></a></h2><p><strong>所谓原子操作，就是执行过程中不能被打断的操作。</strong> 也就是说，<strong>这个操作一旦开始执行，就会一直执行完，中间不会被任何中断或任务切换打断。</strong></p><p>有了原子操作，我们就可以把counter++这样的读-改-写操作，用一个原子操作来完成，这样就不会出现执行到一半被打断的情况了。</p><p>例如，在下图中，counter++这条语句实际上分三步执行：读取counter到寄存器、对寄存器+1、回写到counter。这三步执行的过程中，随时有可能被打断。<strong>而当使用原子操作时，这三步操作会被当作一个整体，要么全部执行完，要么完全不执行，中间不会被打断</strong>。</p><p><img src="'+d+`" alt="原子操作与普通操作对比"></p><p>常见的原子操作有：</p><ol><li><strong>原子加/减</strong>：把内存中的值加上或减去一个数。</li><li><strong>原子比较并交换</strong>：比较内存中的值是否等于预期值，如果相等就换成新值。</li><li><strong>原子交换</strong>：把内存中的值和寄存器的值交换。</li></ol><h2 id="原子操作的实现原理" tabindex="-1"><a class="header-anchor" href="#原子操作的实现原理"><span>原子操作的实现原理</span></a></h2><h3 id="利用cpu的特定指令" tabindex="-1"><a class="header-anchor" href="#利用cpu的特定指令"><span>利用CPU的特定指令</span></a></h3><p>虽然很多CPU并不直接提供&quot;对内存中的值进行加1减1&quot;这样的原子操作指令，但是提供了一些更基础的指令，用于组合起来实现各种原子操作。</p><p>以ARM Cortex-M架构为例，它主要提供了以下几条指令：</p><ol><li><strong>LDREX（独占加载）</strong>：从内存中加载一个值，同时在硬件层面标记这个内存地址已经被独占访问。如果之后有其他任务或中断修改了这个地址，独占标记会被清除。</li><li><strong>STREX（独占存储）</strong>：将一个值存回内存。不过，只有当独占标记还存在的时候才会成功，返回0表示成功；如果独占标记已经被清除了，则存储失败，返回1表示失败。</li><li><strong>CLREX（清除独占标记）</strong>：手动清除当前的独占标记。</li></ol><p>将这三条指令配合起来，实现原子加1操作的汇编代码大致如下：</p><div class="language-asm line-numbers-mode" data-highlighter="shiki" data-ext="asm" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-asm"><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">add_inc</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    LDREX   r0, [r1]      </span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">; 独占加载r1指向的值到r0</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    ADD</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">     r0, r0, #</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">1</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    ; r0加1</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    STREX   r2, r0, [r1]  </span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">; 独占存储r0的值回r1指向的地址，结果存在r2</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    CMP</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">     r2, #</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">0</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">        ; 检查是否存储成功</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    BNE     add_inc       </span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">; 如果失败（r2不等于0），就重试</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我们可以结合下图来理解上述代码的工作原理。例如，有任务A和任务B，同时使用add_inc()对counter进行自增操作：</p><p><img src="`+o+`" alt="LDREX与STREX配合实现原子操作"></p><p>对于上图，各步骤说明如下：</p><ol><li>任务A先执行LDREX：从内存中读到counter=10，同时硬件设置独占标记，表示这个地址正在被独占访问。</li><li>任务A执行ADD：把寄存器里的值加1变成11。</li><li>任务B执行LDREX：读取counter=10，同时重新设置独占标记，任务A之前设置的标记被覆盖。</li><li>任务B执行ADD：寄存器里的值也变成11。</li><li>任务B执行STREX：检查独占标记发现还在，成功把11写回内存，counter变成11。</li><li>任务A继续执行STREX：检查独占标记发现已经没了，写内存失败。</li><li>任务A执行BNE：检查发现失败，跳回add_inc重试。</li></ol><p>通过分析可知，<strong>LDREX + ADD + STREX + 重试循环，组合起来实现了一个原子操作的效果</strong>。虽然add_inc()执行的过程中有可能被打断，但是仍然不影响最终结果的正确性。</p><p>这种实现方式的优点是：<strong>不影响中断响应</strong>，无需关中断。缺点是：<strong>可能会多次重试，有一定的性能开销</strong>。</p><h3 id="利用关中断" tabindex="-1"><a class="header-anchor" href="#利用关中断"><span>利用关中断</span></a></h3><p><strong>原子操作并不一定非要用CPU的特定指令来实现</strong>。如果CPU没有提供相关的原子指令，也可以采用关中断的方式来实现。</p><p>比如，RT-Thread的软件原子加操作是这么实现的：</p><div class="language-c line-numbers-mode" data-highlighter="shiki" data-ext="c" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-c"><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">rt_inline </span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">rt_atomic_t</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> rt_soft_atomic_add</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">volatile</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;"> rt_atomic_t</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> *</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">ptr</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;"> rt_atomic_t</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> val</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">    rt_base_t</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> level</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">    rt_atomic_t</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> temp</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    level </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> rt_hw_interrupt_disable</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">();</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">  /* 关中断 */</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    temp </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> *</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">ptr</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    *</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">ptr </span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">+=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> val</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">    rt_hw_interrupt_enable</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">level</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">);</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">      /* 开中断 */</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">    return</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> temp</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种方式虽然也能保证原子性，但因为关了中断，会影响系统的实时性，效率不如硬件原子指令高。</p><p>不过，<strong>其优点在于较高的可移植性，不依赖特定的CPU指令</strong>。</p><h2 id="rt-thread的原子操作接口" tabindex="-1"><a class="header-anchor" href="#rt-thread的原子操作接口"><span>RT-Thread的原子操作接口</span></a></h2><p>在RT-Thread中，提供了若干常用的原子操作API，这里简要列举部分如下：</p><ol><li><strong>rt_atomic_add(ptr, val)</strong>：原子地将指定地址处的值与给定值相加，返回相加之前的值。</li><li><strong>rt_atomic_sub(ptr, val)</strong>：原子地将指定地址处的值与给定值相减，返回相减之前的值。</li><li><strong>rt_atomic_load(ptr)</strong>：原子地从指定地址加载一个值。</li><li><strong>rt_atomic_store(ptr, val)</strong>：原子地将一个值写入指定地址。</li><li><strong>rt_atomic_exchange(ptr, val)</strong>：原子地将指定地址处的值替换为新值，返回替换之前的值。</li></ol><p>需要说明的是，这些API的实现依赖于不同的平台：有的使用CPU特定指令，有的采用关中断方式。用户不需要关心底层实现，直接调用即可。</p><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>综上所述，原子操作就是执行过程中不能被打断的操作，用来解决多任务环境下的竞态条件问题。</p><p>原子操作的实现方式有两种：一种是直接利用CPU提供的特殊指令；另一种是利用关中断。具体采用哪一种，取决于所用的CPU架构。</p><hr>`,38)),i("blockquote",null,[s[1]||(s[1]=i("p",null,"如果你希望系统地学习RTOS底层原理，可以了解我的《RTOS开发与实战》课程。",-1)),s[2]||(s[2]=i("p",null,"课程不是简单地讲解FreeRTOS API的使用，而是带你从零开始编写一个RTOS内核，逐步实现任务管理、任务调度、上下文切换、同步与通信等核心机制，并通过一个远程温湿度监控设备项目，将操作系统原理应用到实际嵌入式开发中。",-1)),s[3]||(s[3]=i("p",null,"适合希望深入理解RTOS工作原理、提升嵌入式底层开发能力的同学。",-1)),i("p",null,[l(a,{href:"/blog/diyrtos/"},{default:r(()=>[...s[0]||(s[0]=[k("课程详情",-1)])]),_:1})])])])}const E=n(g,[["render",c]]),u=JSON.parse('{"path":"/tech/rtos100/n4s1cmzz/","title":"什么是原子指令，有哪些原子操作","lang":"zh-CN","frontmatter":{"title":"什么是原子指令，有哪些原子操作","createTime":"2026/11/10 14:55:22","permalink":"/tech/rtos100/n4s1cmzz/","description":"当工程中引入RT-Thread等RTOS后，我们经常会碰到多任务访问共享资源冲突的问题： 例如，两个任务同时对全局变量counter进行自增操作时，有可能出现最终自增结果错误的问题。 要解决这个问题，常见的做法是利用关中断或者互斥锁来保护，避免操作过程中被打断。 不过，对于counter++这种简单的操作，使用关中断或互斥锁有点杀鸡用牛刀的感觉。 实际...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"什么是原子指令，有哪些原子操作\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://lishutong1024.cn/tech/rtos100/n4s1cmzz/"}],["meta",{"property":"og:site_name","content":"李述铜的嵌入式课堂"}],["meta",{"property":"og:title","content":"什么是原子指令，有哪些原子操作"}],["meta",{"property":"og:description","content":"当工程中引入RT-Thread等RTOS后，我们经常会碰到多任务访问共享资源冲突的问题： 例如，两个任务同时对全局变量counter进行自增操作时，有可能出现最终自增结果错误的问题。 要解决这个问题，常见的做法是利用关中断或者互斥锁来保护，避免操作过程中被打断。 不过，对于counter++这种简单的操作，使用关中断或互斥锁有点杀鸡用牛刀的感觉。 实际..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":6.16,"words":1848},"git":{},"autoDesc":true,"filePathRelative":"notes/tech/rtos100/irq/q84.md","headers":[],"bulletin":true}');export{E as comp,u as data};
